cat > main.ts <<'EOF'
const path = Deno.args[0];
if (path === undefined) {
  console.error("usage: main.ts <file>");
  Deno.exit(2);
}

const data = Deno.readFileSync(path);
const counts = new Map<string, number>();
let word = "";
const flush = () => {
  if (word !== "") {
    counts.set(word, (counts.get(word) ?? 0) + 1);
    word = "";
  }
};
for (const b of data) {
  if (b >= 0x30 && b <= 0x39) word += String.fromCharCode(b);
  else if (b >= 0x61 && b <= 0x7a) word += String.fromCharCode(b);
  else if (b >= 0x41 && b <= 0x5a) word += String.fromCharCode(b + 32);
  else flush();
}
flush();

const entries = [...counts.entries()].sort((a, b) =>
  b[1] - a[1] || (a[0] < b[0] ? -1 : a[0] > b[0] ? 1 : 0)
);
const out = entries.slice(0, 10).map(([w, c]) => `${w} ${c}`);
if (out.length > 0) Deno.stdout.writeSync(new TextEncoder().encode(out.join("\n") + "\n"));
EOF
